#[test]
#[expected_failure(abort_code = protocol::error::Err_Referral_Already_Has_Referral_Code, location = protocol::referral)]
fun generate_referral_code_already_exists_test() {
    let mut scenario = ts::begin(ADMIN);
    random::create_for_testing(scenario.ctx());

    let mut referral = new(
        500,  // referrer_discount_bps: 5%
        400,  // referee_discount_bps: 4%
        10_000, // referrer_deposit_usd_threshold: $10000
        scenario.ctx()
    );

    // first time
    referral.set_accumulated_deposit_usd_for( USER1, 10_001);
    scenario.next_tx(USER1);
    {
        let random = scenario.take_shared<Random>();
        referral.generate_referral_code( &random, scenario.ctx());
        ts::return_shared(random);
    };

    // second time
    scenario.next_tx( USER1);
    {
        let random = scenario.take_shared<Random>();
        referral.generate_referral_code( &random, scenario.ctx());
        ts::return_shared(random);
    };

    std::unit_test::destroy(referral);
    ts::end(scenario);
}

